(()=>{(async function(){let o=/\/courses\/([0-9]+)\/question_banks\/([0-9]+)/,s=window.location.pathname.match(o),a=s[1],i=s[2];$("#questions .question_holder").each(function(){let n=$(this).find(".question"),e=n.attr("id").match("d+");if(e)e=e[0];else return;let t=$('<a href="#" class="no-hover" title="Duplicate this Question"><i class="icon-plus standalone-icon"><span class="screenreader-only">Duplicate this Question</span></i></a>');t.click(function(){u(e)}),n.find(".links").prepend(t)});async function u(n){let e=window.location.origin+"/courses/"+a+"/question_banks/"+i+"/move_questions",t={};t[n]=1,await $.post(e,{multiple_questions:0,assessment_question_bank_id:i,copy:1,move:0,questions:t}),location.reload()}})();})();
